                    continue
                q = deque([(r, c)])
                seen.add((r, c))
                comp = []
                while q:
                    p = q.popleft()
                    comp.append(p)
                    for nr, nc in ((p[0]-1,p[1]), (p[0]+1,p[1]),
                                   (p[0],p[1]-1), (p[0],p[1]+1)):
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color and (nr,nc) not in seen:
                            seen.add((nr,nc))
                            q.append((nr,nc))
                comps.setdefault(color, []).append(comp)

    # Marker is a connected thin line: one component with a long straight run.
    marker = None
    for color, groups in comps.items():
        for comp in groups:
            rows = [r for r, c in comp]
            cols = [c for r, c in comp]
            height = max(rows) - min(rows) + 1
            width = max(cols) - min(cols) + 1
            if len(comp) >= 8 and (height >= 8 or width >= 8):
                marker = color
                break
        if marker is not None:
            break

    if marker is None:
        return [row[:] for row in grid]

    # Recolor the color whose largest connected object is largest.
    candidates = {c: max(map(len, groups)) for c, groups in comps.items()
                  if c != marker}
    if not candidates:
        return [row[:] for row in grid]
    target = max(candidates, key=candidates.get)
